function dump(node, depth, maxDepth) {
  const indent = '  '.repeat(depth);
  let out = indent + node.type + ' "' + node.name + '"';
  if ('width' in node) out += ` ${Math.round(node.width * 10) / 10}x${Math.round(node.height * 10) / 10}`;
  try {
    if ('fills' in node && Array.isArray(node.fills) && node.fills.length) {
      out += ' fills=' + JSON.stringify(node.fills.map(f => {
        if (f.type === 'SOLID') return { t: 'S', hex: [f.color.r, f.color.g, f.color.b].map(v => Math.round(v * 255).toString(16).padStart(2, '0')).join(''), o: f.opacity };
        if (f.type === 'IMAGE') return { t: 'IMG', mode: f.scaleMode };
        return f.type;
      }));
    }
  } catch (e) {}
  if ('constraints' in node) out += ' cons=' + node.constraints.horizontal + '/' + node.constraints.vertical;
  if ('cornerRadius' in node && node.cornerRadius !== figma.mixed) out += ' r=' + node.cornerRadius;
  if ('layoutMode' in node && node.layoutMode !== 'NONE') out += ' layout=' + node.layoutMode + (node.layoutSizingHorizontal ? ' w:' + node.layoutSizingHorizontal : '') + (node.layoutSizingVertical ? ' h:' + node.layoutSizingVertical : '');
  if (node.type === 'TEXT') {
    out += ' font=' + node.fontName.family + '/' + node.fontName.style + ' sz=' + JSON.stringify(node.fontSize);
    try { out += ' dec=' + node.textDecoration; } catch (e) {}
  }
  out += '\n';
  if ('children' in node && depth < maxDepth) for (const c of node.children) out += dump(c, depth + 1, maxDepth);
  return out;
}
